#!/usr/bin/env bash
# Reproduce the real-validation numbers of 'c2r' (model-v2x-track/routed-c2r) from the checkpoints: realval-A/B inference of every used
# member with its committed post-processing, bag fusion, merge with model.yaml, official metric, comparison with
# validation/results/scorecard.json. Needs the prepared real validation data and the checkpoints. Generated by
# common/tools/reproduce_validation.py. Run on an idle GPU:
#   CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-c2r/test/reproduce_c2r_validation.sh
# The inference commands are independent: `python common/tools/reproduce_validation.py model-v2x-track/routed-c2r --tag c2r --jobs`
# prints them, one per line, for running several GPUs at once.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
mkdir -p model-v2x-track/routed-c2r/validation/output/repro_c2r
[ -s model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta_val.json
[ -s model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta_valB.json
[ -s model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6d2_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d2 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6d2/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6d2_tta_val.json
[ -s model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6d2_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d2 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v6d2/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6d2_tta_valB.json
[ -s model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6d3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d3 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6d3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6d3_tta_val.json
