[ -s model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta__6_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta__6_val.json
[ -s model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta__6_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c2r/validation/output/repro_c2r/voxelrcnn-ros-g1v6_tta__6_valB.json
